mapper.select:
SELECT data_server
FROM data_management
WHERE data_name = #{dataName}

SELECT node_name
FROM node_management
WHERE node_id = #{nodeId}

SELECT node_id
FROM node_management
WHERE node_name = #{nodeName}

SELECT data_size
FROM data_management
WHERE data_name = #{dataName}

SELECT (latency + (#{dataSize} / bandwidth)) AS t1
FROM edge_management
WHERE source_id = #{sourceId}
AND target_id = #{targetId}
ORDER BY latency + (#{dataSize} / bandwidth) ASC
LIMIT 1

SELECT bandwidth
FROM real_edge_management
WHERE source_id = #{sourceId}
AND target_id = #{targetId}

mapper.update:
UPDATE task_management
status = #{status}, schedule = #{schedule}, data_preparation_ms = #{dataPreparationMs}, compute_duration_ms = #{computeDurationMs}, execution_evidence_complete = #{executionEvidenceComplete}, started_at = #{startedAt}, finished_at = #{finishedAt}, task_id = task_id
WHERE task_id = #{taskId}

mapper.select:
SELECT * FROM task_execution_event
WHERE task_id = #{taskId}
ORDER BY occurred_at ASC, event_id ASC

SELECT * FROM task_management
WHERE acceptance_run_id = #{acceptanceRunId}
  AND run_round = #{runRound}
ORDER BY create_time DESC, task_id DESC
